//! Agent guidance for integrated HTML reports. The marker and variable names
//! are the contract implemented by the app's inline HTML view.

pub(crate) const REPORT_GUIDANCE: &str = "Grove renders HTML reports inline in the conversation. When a visual report, chart, dashboard or comparison communicates better than prose, write one complete, self-contained HTML document (inline CSS and JavaScript, data: URLs only; network and file requests are blocked) as a fenced html block or as a local .html file linked in Markdown. Include the exact comment <!-- grove:integrated-report --> so Grove themes it and sizes it to its content. Style it with Grove's CSS variables instead of fixed colours: --grove-bg, --grove-fg, --grove-muted, --grove-surface, --grove-border, --grove-info, --grove-success, --grove-warning, --grove-font, --grove-body, --grove-title, --grove-display, --grove-gap, --grove-section and --grove-radius. Avoid viewport-height layouts, inner scroll areas, fixed or sticky positioning, and body margins. Prefer prose for answers that do not need a visual.";
